import {
  Config,
  Context,
  Duration,
  Effect,
  Layer,
  Option,
  Schema,
} from "effect";

import { CodexLocalProfileImportError } from "./errors.js";
import { CodexLocalProfileImportConfig } from "./schemas.js";
import type { CodexLocalProfileImportConfig as CodexLocalProfileImportConfigType } from "./schemas.js";

const localAuthFileConfig = Config.option(
  Config.schema(Schema.NonEmptyString, "BUNDJIL_CODEX_LOCAL_AUTH_FILE")
);

const homeDirectoryConfig = Config.option(Config.nonEmptyString("HOME"));

const principalIdConfig = Config.schema(
  Schema.NonEmptyString,
  "BUNDJIL_CODEX_PROFILE_PRINCIPAL_ID"
);

const connectorIdConfig = Config.schema(
  Schema.NonEmptyString.pipe(Schema.brand("CodexOAuthConnectorId")),
  "BUNDJIL_CODEX_PROFILE_CONNECTOR_ID"
);

const installationIdConfig = Config.schema(
  Schema.NonEmptyString.pipe(Schema.brand("CodexOAuthInstallationId")),
  "BUNDJIL_CODEX_PROFILE_INSTALLATION_ID"
);

const profileIdConfig = Config.schema(
  Schema.NonEmptyString.pipe(Schema.brand("CodexOAuthProfileId")),
  "BUNDJIL_CODEX_PROFILE_ID"
);

const accessTokenTtlConfig = Config.duration(
  "BUNDJIL_CODEX_LOCAL_ACCESS_TOKEN_TTL"
).pipe(Config.withDefault(Duration.hours(1)));

export class CodexLocalProfileImportConfigService extends Context.Service<
  CodexLocalProfileImportConfigService,
  CodexLocalProfileImportConfigType
>()("@bundjil/codex-oauth/CodexLocalProfileImportConfig") {}

export const loadCodexLocalProfileImportConfig = Effect.gen(
  function* loadCodexLocalProfileImportConfigFromProvider() {
    const configuredLocalAuthFile = yield* localAuthFileConfig;
    const homeDirectory = yield* homeDirectoryConfig;
    const principalId = yield* principalIdConfig;
    const connectorId = yield* connectorIdConfig;
    const installationId = yield* installationIdConfig;
    const profileId = yield* profileIdConfig;
    const accessTokenTtl = yield* accessTokenTtlConfig;

    const localAuthFile = Option.match(configuredLocalAuthFile, {
      onNone: () =>
        Option.match(homeDirectory, {
          onNone: () => null,
          onSome: (home) => `${home}/.codex/auth.json`,
        }),
      onSome: (path) => path,
    });

    return yield* Schema.decodeUnknownEffect(CodexLocalProfileImportConfig)({
      localAuthFile,
      subject: {
        provider: "codex",
        principal: {
          type: "chatgpt-user",
          id: principalId,
          issuer: "https://auth.openai.com",
        },
        connectorId,
        installationId,
        profileId,
      },
      accessTokenTtlMillis: Duration.toMillis(accessTokenTtl),
    }).pipe(
      Effect.mapError(
        () =>
          new CodexLocalProfileImportError({
            operation: "loadConfig",
            message: "Unable to load local Codex profile import config.",
          })
      )
    );
  }
).pipe(Effect.withSpan("CodexLocalProfileImportConfig.load"));

export const CodexLocalProfileImportConfigLive = Layer.effect(
  CodexLocalProfileImportConfigService,
  loadCodexLocalProfileImportConfig
);
import { Config, Context, Duration, Effect, Layer, Schema } from "effect";

import { CodexSubscriptionAuthError } from "./errors.js";
import { CodexSubscriptionLoginInput } from "./schemas.js";
import type { CodexSubscriptionLoginInput as CodexSubscriptionLoginInputType } from "./schemas.js";

const principalIdConfig = Config.schema(
  Schema.NonEmptyString,
  "BUNDJIL_CODEX_PROFILE_PRINCIPAL_ID"
);

const connectorIdConfig = Config.schema(
  Schema.NonEmptyString.pipe(Schema.brand("CodexOAuthConnectorId")),
  "BUNDJIL_CODEX_PROFILE_CONNECTOR_ID"
).pipe(Config.withDefault("bundjil-local"));

const installationIdConfig = Config.schema(
  Schema.NonEmptyString.pipe(Schema.brand("CodexOAuthInstallationId")),
  "BUNDJIL_CODEX_PROFILE_INSTALLATION_ID"
).pipe(Config.withDefault("agent-dev"));

const profileIdConfig = Config.schema(
  Schema.NonEmptyString.pipe(Schema.brand("CodexOAuthProfileId")),
  "BUNDJIL_CODEX_PROFILE_ID"
).pipe(Config.withDefault("default"));

const callbackTimeoutConfig = Config.duration(
  "BUNDJIL_CODEX_LOGIN_CALLBACK_TIMEOUT"
).pipe(Config.withDefault(Duration.minutes(5)));

export class CodexSubscriptionLoginConfigService extends Context.Service<
  CodexSubscriptionLoginConfigService,
  CodexSubscriptionLoginInputType
>()("@bundjil/codex-oauth/CodexSubscriptionLoginConfig") {}

export const loadCodexSubscriptionLoginConfig = Effect.gen(
  function* loadCodexSubscriptionLoginConfigOperation() {
    const principalId = yield* principalIdConfig;
    const connectorId = yield* connectorIdConfig;
    const installationId = yield* installationIdConfig;
    const profileId = yield* profileIdConfig;
    const callbackTimeout = yield* callbackTimeoutConfig;

    return yield* Schema.decodeUnknownEffect(CodexSubscriptionLoginInput)({
      subject: {
        provider: "codex",
        principal: {
          type: "chatgpt-user",
          id: principalId,
          issuer: "https://auth.openai.com",
        },
        connectorId,
        installationId,
        profileId,
      },
      callbackTimeoutMillis: Duration.toMillis(callbackTimeout),
    }).pipe(
      Effect.mapError(
        () =>
          new CodexSubscriptionAuthError({
            operation: "completeLogin",
            reason: "tokenMetadataInvalid",
            message: "Unable to load the trusted-local login configuration.",
          })
      )
    );
  }
);

export const CodexSubscriptionLoginConfigLive = Layer.effect(
  CodexSubscriptionLoginConfigService,
  loadCodexSubscriptionLoginConfig
);
import { Config, Context, Effect, Layer, Schema } from "effect";

import { CodexOAuthProfileCipherError } from "./errors.js";
import type { CodexOAuthProfileCipherConfig } from "./schemas.js";

const encryptionAlgorithmConfig = Config.schema(
  Schema.Literal("AES-GCM"),
  "BUNDJIL_CODEX_PROFILE_ENCRYPTION_ALGORITHM"
).pipe(Config.withDefault("AES-GCM"));

const encryptionKeyIdConfig = Config.schema(
  Schema.NonEmptyString.pipe(Schema.brand("CodexOAuthProfileCipherKeyId")),
  "BUNDJIL_CODEX_PROFILE_ENCRYPTION_KEY_ID"
);

const encryptionKeyMaterialConfig = Config.redacted(
  "BUNDJIL_CODEX_PROFILE_ENCRYPTION_KEY"
);

export class CodexOAuthProfileCipherConfigService extends Context.Service<
  CodexOAuthProfileCipherConfigService,
  CodexOAuthProfileCipherConfig
>()("@bundjil/codex-oauth/CodexOAuthProfileCipherConfig") {}

export const loadCodexOAuthProfileCipherConfig = Effect.gen(
  function* loadCodexOAuthProfileCipherConfigFromProvider() {
    const algorithm = yield* encryptionAlgorithmConfig;
    const keyId = yield* encryptionKeyIdConfig;
    const keyMaterial = yield* encryptionKeyMaterialConfig;

    return {
      algorithm,
      keyId,
      keyMaterial,
    } satisfies CodexOAuthProfileCipherConfig;
  }
).pipe(
  Effect.mapError(
    () =>
      new CodexOAuthProfileCipherError({
        operation: "loadKey",
        message: "Unable to load Codex OAuth profile encryption config.",
      })
  ),
  Effect.withSpan("CodexOAuthProfileCipherConfig.load")
);

export const CodexOAuthProfileCipherConfigLive = Layer.effect(
  CodexOAuthProfileCipherConfigService,
  loadCodexOAuthProfileCipherConfig
);
import {
  Config,
  ConfigProvider,
  Effect,
  Option,
  Redacted,
  Schema,
} from "effect";

import { CodexResponsesRequestError } from "./errors.js";
import {
  CodexResponsesEndpoint,
  CodexResponsesModelId,
  CodexResponsesProofInput,
} from "./schemas.js";

export const defaultCodexResponsesEndpoint =
  "https://chatgpt.com/backend-api/codex/responses";

export const defaultCodexResponsesModel = "gpt-5.5";

const proofAccessTokenConfig = Config.redacted("CODEX_ACCESS_TOKEN");

const proofAccountIdConfig = Config.option(
  Config.schema(Schema.NonEmptyString, "BUNDJIL_CODEX_ACCOUNT_ID")
);

const proofModelConfig = Config.schema(
  CodexResponsesModelId,
  "BUNDJIL_CODEX_MODEL"
).pipe(Config.withDefault(defaultCodexResponsesModel));

const proofPromptConfig = Config.schema(
  Schema.NonEmptyString,
  "BUNDJIL_CODEX_PROOF_PROMPT"
).pipe(Config.withDefault("Reply with OK."));

export const codexResponsesEndpointConfig = Config.schema(
  CodexResponsesEndpoint,
  "BUNDJIL_CODEX_RESPONSES_ENDPOINT"
).pipe(Config.withDefault(defaultCodexResponsesEndpoint));

export const loadCodexResponsesProofInput = Effect.gen(
  function* loadCodexResponsesProofInputFromConfig() {
    const rawAccessToken = yield* proofAccessTokenConfig;
    const accountId = yield* proofAccountIdConfig;
    const model = yield* proofModelConfig;
    const prompt = yield* proofPromptConfig;

    return yield* Schema.decodeUnknownEffect(CodexResponsesProofInput)({
      accessToken: Redacted.value(rawAccessToken),
      ...(Option.isNone(accountId) ? {} : { accountId: accountId.value }),
      model,
      prompt,
    }).pipe(
      Effect.mapError(
        (cause) =>
          new CodexResponsesRequestError({
            boundary: "CodexResponsesProofInput",
            message: "Unable to decode Codex Responses proof config.",
            cause,
          })
      )
    );
  }
);

export const loadCodexResponsesProofInputFromEnv =
  loadCodexResponsesProofInput.pipe(
    Effect.provide(ConfigProvider.layer(ConfigProvider.fromEnv()))
  );

